** debug_mode.c
*/

#include "my_tetris.h"

int disp_key_bindings(char const *str, char *key)
{
    my_putstr(str);
    if (key[0] == 27)
        write(1, "^E", 2);
    if (key[1] == 't')
        return (my_putstr("(tab)\n"));
    if (key[1] == 'n')
        return (my_putstr("(enter)\n"));
    if (key[0] == ' ')
        return (my_putstr("(space)\n"));
    if (key[0] ^ 27)
        my_putstr(key);
    else
        my_putstr(&key[1]);
    return (write(1, "\n", 1));
}

int debug_mode(options_t *opt)
{
    if (opt->debug) {
        my_putstr("*** DEBUG MODE ***\n");
        disp_key_bindings("Key Left :  ", opt->keys.left);
        disp_key_bindings("Key Right :  ", opt->keys.right);
        disp_key_bindings("Key Turn :  ", opt->keys.turn);
        disp_key_bindings("Key Drop :  ", opt->keys.drop);
        disp_key_bindings("Key Quit :  ", opt->keys.quit);
        disp_key_bindings("Key Pause :  ", opt->keys.pause);
        disp_key_bindings("Next :  ", (opt->hide == false) ? "Yes" : "No");
        mprintf("Level :  %u", opt->level);
        mprintf("\nSize :  %u*%u\n", opt->size.row, opt->size.col);
        if (debug_tetriminos(opt, 1) == 84)
            return (EXIT_ERROR);
        my_putstr("Press any key to start Tetris\n");
        if (wait_input() == 84)
            return (EXIT_ERROR);
    } else if (debug_tetriminos(opt, 0) == 84)
        return (EXIT_ERROR);
    return (EXIT_SUCCESS);
}

bool check_right_extension(char const *name)
{
    int size = my_strlen(name);

    if (size <= 10 || name == NULL) {
        return (false);
    }
    if (my_strcmp(&name[size - 10], ".tetrimino") != 0) {
        return (false);
    }
    return (true);
}

int debug_tetriminos(options_t *opt, int cas)
{
    DIR *folder = opendir("./tetriminos/");
    DIR *size = opendir("./tetriminos/");

    opt->nbr_tetrimino = 0;
    if (!folder || !size)
        return (my_putstr("Tetriminos : Error\n"));
    for (struct dirent *tmp = readdir(size); tmp; tmp = readdir(size))
        opt->nbr_tetrimino += check_right_extension(tmp->d_name);
    if (opt->nbr_tetrimino == 0)
        return (EXIT_SUCCESS);
    closedir(size);
    if (read_file_info(opt, folder) == 84)
        return (EXIT_ERROR);
    if (cas == 1) {
        mprintf("Tetriminos :  %d\n", size_list(opt));
        sort_alphabetically(opt);
        display_debug_mode_file_part(opt);
    }
    closedir(folder);
    return (EXIT_SUCCESS);
}

sources/display_tetriminos_file_data.c.content:
/*
** EPITECH PROJECT, 2019
** analyze_tetriminos.c
** File description:
** analyzation of tetriminos directory
*/

#include "my_tetris.h"

char *change_name_of_file(char *name)
{
    int size = my_strlen(name);

    if (size <= 10 || name == NULL)
        return (name);
    name[size - 10] = '\0';
    return (name);
}

int display_file_data(tetrimino_t *tetris)
{
    for (int i = 0; tetris->tetrimino && tetris->tetrimino[i]; i++) {
        write(1, tetris->tetrimino[i], my_strlen(tetris->tetrimino[i]));
        write(1, "\n", 1);
    }
    return (0);
}

int display_name_file(tetrimino_t *tetris)
{
    if (tetris == NULL)
        return (1);
    for (int i = 0; tetris->name && tetris->name[i]; i++)
        write(1, &tetris->name[i], 1);
    if (tetris->col == -1 || tetris->color == -1 ||
        tetris->row == -1 || tetris->tetrimino == NULL)
        return (1);
    return (0);
}

int display_debug_mode_file_part(options_t *opt)
{
    int check_error = 0;
    tetrimino_t *tetris = opt->map;

    for (int i = 0; tetris; i++, check_error = 0, tetris = tetris->next) {
        my_putstr("Tetriminos :  Name ");
        check_error = display_name_file(tetris);
        if (check_error == 0) {
            my_putstr(" :  Size ");
            my_putnbr(tetris->col);
            my_putchar('*');
            my_putnbr(tetris->row);
            my_putstr(" :  Color ");
            my_putnbr(tetris->color);
            my_putstr(" :\n");
            display_file_data(tetris);
        } else
            my_putstr(" :  Error\n");
    }
    return (0);
}

