int check_end_line(char *buffer, int return_read)
{
    int solv = -1;
    int i = 0;
    static char *prev_buffer = NULL;

    if (buffer != NULL) {
        for (; buffer[i] != '\0'; i++)
            if (buffer[i] == '\n') {
                solv = 1;
                break;
            }
        if (solv != -1)
            solv = i;
        else if (return_read == 0 && prev_buffer != buffer && i != 0) {
            solv = i;
            prev_buffer = buffer;
        }
    }
    else
        return (-1);
    return (solv);
}

char *rework_buffer(char *buffer, int *read_y, int *nbr_charac)
{
    int i = 0;
    int i_two = 0;
    int size = 0;

    for (i = 0; buffer && buffer[i] != '\0'; i++)
        if (buffer[i] == '\n')
            break;
    if ((*nbr_charac = check_end_line(buffer, -1)) != -1)
        i++;
    for (size = 0; buffer && buffer[size] != '\0'; size++);
    if (size > 1 || (size == 1 && buffer && buffer[0] == '\n'))
        for (; buffer && buffer[i] != '\0'; i++, i_two++)
            buffer[i_two] = buffer[i];
    buffer[i_two] = '\0';
    if (*nbr_charac < 0 && check_end_line(buffer, -1) != -1) {
        *read_y = 0;
        *nbr_charac = check_end_line(buffer, -1);
    }
    return (buffer);
}

char *is_algo(int fd, int *line, int read_y, int *nbr)
{
    static char *buffer = NULL;
    static int nbr_ = 0;
    static int ret_read = 0;
    char *reader = malloc(sizeof(char) * READ_SIZE);

    if (*line != 0 && read_y != 0 && buffer != NULL)
        buffer = rework_buffer(buffer, &read_y, &nbr_);
    reader = clear_buffer(reader, line);
    while ((read_y == 1) && (ret_read = read(fd, reader, READ_SIZE) > 0)) {
        if (ret_read == -1 || reader == NULL)
            return (NULL);
        buffer = my_strcat_two(buffer, reader);
        reader = clear_reader(reader);
        if ((nbr_ = check_end_line(buffer, ret_read)) != -1 || ret_read <= 0)
            break;
    }
    if ((buffer) || (is_end_algo(ret_read, buffer, read_y) == NULL) ||
        (ret_read == 0 && (nbr_ = check_end_line(buffer, ret_read)) == -1))
        return (NULL);
    return (is_end_algo_two(reader, nbr, nbr_, buffer));
}

