char *error_operation_system(int errnum)
{
    switch (errnum) {
    case EALREADY: return ("Operation already in progress.\n");
    case EPERM: return ("Operation not permitted.\n");
    case EOPNOTSUPP | ENOTSUP: return ("Operation not supported.\n");
